n": 0, "market_extra": 0.35}, {"id": "excel-10", "menu_key": "tagliere_formaggi:medio", "approved": true, "name": "Tagliere formaggi", "variant": "Media", "source_price": 23, "raw_cost": 4.389192309999999, "confidence": "Bassa", "notes": "Metà dei formaggi valorizzati + miele/frutta secca/accomp. ~0,35€; quantità reali ignote.", "review": "", "source_row": 10, "base_cost": 4.03919231, "correction": 0, "market_extra": 0.35}, {"id": "excel-11", "menu_key": "tagliere_formaggi:entero", "approved": true, "name": "Tagliere formaggi", "variant": "Entera", "source_price": 30, "raw_cost": 8.62838462, "confidence": "Media", "notes": "5 formaggi documentati; aggiunta orientativa miele, frutta secca e accompagnamento.", "review": "", "source_row": 11, "base_cost": 8.07838462, "correction": 0, "market_extra": 0.55}, {"id": "excel-12", "menu_key": "carpaccio_bresaola", "approved": true, "name": "Carpaccio di bresaola", "variant": null, "source_price": 19.5, "raw_cost": 8.39133333, "confidence": "Media", "notes": "Aggiunta olio/balsamico ~0,20€; bresaola 200g in ricetta: controllare porzione.", "review": "", "source_row": 12, "base_cost": 8.19133333, "correction": 0, "market_extra": 0.2}, {"id": "excel-13", "menu_key": "caprese", "approved": true, "name": "Caprese", "variant": null, "source_price": 15.5, "raw_cost": 1.6556666667000002, "confidence": "Bassa", "notes": "La ricetta precedente costava burrata 125g: sostituita con 125g fiordilatte a 10,453 €/kg + olio/basilico.", "review": "", "source_row": 13, "base_cost": 1.979, "correction": -0.4533333333, "market_extra": 0.13}, {"id": "excel-14", "menu_key": "burrata_anchoas_tomate_seco", "approved": true, "name": "Burrata, alici e pomodoro secco", "variant": null, "source_price": 16.5, "raw_cost": 5.75668421, "confidence": "Media", "notes": "½ scatoletta alici (2€) confermata; extra olio/balsamico ~0,12€.", "review": "", "source_row": 14, "base_cost": 5.63668421, "correction": 0, "market_extra": 0.12}, {"id": "excel-15", "menu_key": "bruschetta_lardo_colonnata_taleggio", "approved": true, "name": "Bruschetta lardo e taleggio", "variant": null, "source_price": 13.5, "raw_cost": 2.1322, "confidence": "Media", "notes": "Pane fatto in casa stimato nell’Excel precedente; aggiunta olio ~0,10€.", "review": "", "source_row": 15, "base_cost": 2.0322, "correction": 0, "market_extra": 0.1}, {"id": "excel-16", "menu_key": "crostone_salsiccia_taleggio", "approved": false, "name": "Bruschetta stracchino e salsiccia", "variant": null, "source_price": 13.5, "raw_cost": 1.730625, "confidence": "Bassa", "notes": "Pane stimato e mezza salsiccia 75g ipotizzata; olio ~0,10€.", "review": "Stracchino nel file, taleggio in carta", "source_row": 16, "base_cost": 1.630625, "correction": 0, "market_extra": 0.1}, {"id": "excel-17", "menu_key": "melanzane_alla_parmigiana", "approved": true, "name": "Melanzane alla parmigiana", "variant": null, "source_price": 13.5, "raw_cost": 1.7862923077000001, "confidence": "Bassa", "notes": "Ricetta non valorizzava provola: ipotesi 50g×11,65€/kg + olio/frittura 0,15€.", "review": "", "source_row": 17, "base_cost": 1.0536, "correction": 0.5826923077, "market_extra": 0.15}, {"id": "excel-18", "menu_key": "mozzarella_carrozza_anchoas", "approved": true, "name": "Mozzarella in carrozza con alici", "variant": null, "source_price": 12.5, "raw_cost": 1.00813333, "confidence": "Media", "notes": "Aggiunta panatura/uovo/olio di frittura circa 0,30€; fonti locali pan grattato/olio.", "review": "", "source_row": 18, "base_cost": 0.70813333, "correction": 0, "market_extra": 0.3}, {"id": "excel-19", "menu_key": null, "approved": false, "name": "Crocchette papas, provola e guanciale", "variant": null, "source_price": 15.5, "raw_cost": 1.59945513, "confidence": "Bassa", "notes": "Panatura 0,20€ già stimata; aggiunto assorbimento olio 0,15€; resa impasto 18 porzioni incerta.", "review": "", "source_row": 19, "base_cost": 1.44945513, "correction": 0, "market_extra": 0.15}, {"id": "excel-20", "menu_ke