i"], [], ["Prodotto riferimento Tenerife", "Prezzo osservato", "Formato", "Fonte URL", "Uso nel modello"], ["HiperDino brotes", 1.32, "70 g", "https://www.hiperdino.es/c9509/frescos/verduras-y-hortalizas.html?p=2", "0,66€ mezza busta già nel costo insalata mista"], ["HiperDino rúcula", 1.98, "100 g", "https://www.hiperdino.es/c9509/frescos/verduras-y-hortalizas.html?p=2", "Conferma ordine di grandezza del proxy 1,99€/100g"], ["Abril olio EVO", 5.39, "1 L", "https://www.hiperdino.es/c9500/alimentacion/aceites.html", "Indicatore 5,39€/L, quota per piatto calcolata tecnicamente"], ["HiperDino olio girasole", 1.66, "1 L", "https://www.hiperdino.es/c9499/alimentacion/aceites.html", "Riferimento assorbimento olio frittura"], ["Ifa Eliges pan rallado", 0.67, "500 g", "https://www.hiperdino.es/c9500/alimentacion.html?p=101", "0,04€ per ~30g pangrattato, stima panatura"], ["HiperDino café molido natural", 2.2, "250 g", "https://www.hiperdino.es/c9500/alimentacion.html?p=19", "Proxy caffè tiramisù; dose ancora da confermare"], [], [], ["Documento di partenza", "File/URL", "Copertura", "Nota", null], ["Food cost base", "Nonna_Angela_Food_Cost_Stimato_Scenari_27_10_2026.xlsx", "29 ricette, 3 scenari", "Solo basi senza olio, scarti e manodopera", null], ["Conferme Dani", "Nonna_Angela_Food_Cost_Raw_2026_v3_conrisposte.xlsx", "39 conferme e risposte", "Rese/grammature da verificare", null], ["Prezzo menù", "Nonna_Angela_Carta_Completa_Solo_Primi_Meno30_Arrotondati.pdf", "29 voci, varianti aggiuntive taglieri", "Primi -30% e arrotondamento per difetto a 0,00/0,50", null], ["Fatture originali", "Facturas octubre.pdf, facturas 1.pdf, Orthidal", "Materie prime storiche", "Prezzi di acquisto veri privilegiati a confronto dei proxy", null]], "verification": [["CHECKLIST PRIORITARIA PER DANI · VARIABILI CRITICHE", null, null, null], [], ["Priorità", "Piatti", "Dato da ottenere", "Motivo"], ["1", "Arrosticini", "8 pezzi = 240g davvero? Acquisto €/kg e peso reale porzione", "Precedente ricetta costava 12 pezzi; differenza economica significativa"], ["1", "Lasagne", "Grammatura Parmigiano, costo/resa ragù (carne+pomodoro) e peso porzione", "Costi base sottostimati se mancano formaggi e scarti"], ["1", "Cannolo", "40g di pistacchio effettivo? Ricotta oppure panna?", "Il costo dei pistacchi è elevato; descrizione menu differisce dalla ricetta"], ["1", "Babà", "Quanto rum usate per pezzo? Base babà e panna reali?", "Food cost già oltre 25%, senza dosaggio liquore confermato"], ["1", "Carpaccio", "Bresaola davvero 200 g? Grana 50g?", "Incidenza ingredienti >25%"], ["1", "Tagliere", "Quanti grammi salumi e formaggi nei mezzi e negli interi?", "Stima 50% mezzo tagliere può essere errata"], ["2", "Caponata", "Olive e pomodoro: pesi, prezzo, resa, olio", "Carta differente da vecchia ricetta Dani"], ["2", "Parmigiana", "Grammi provola, olio e resa reale porzione", "Provola era presente nel menu ma non nel costo"], ["2", "Crocchette", "Pesare lotto finale, resa 18 porzioni, quantità panatura e olio", "8,05 kg ingredienti iniziali vs 4,32 kg di prodotto finito"], ["2", "Caprese", "Fiordilatte anziché burrata? 125g a piatto?", "Ricetta precedente differiva dal menu"], ["2", "Salse e pesto", "Rese vere sugo/pesto/bisque e g parmigiano nel pesto", "Costi preparazioni dipendono da rese ipotizzate"]]}'::jsonb) ON CONFLICT (id) DO NOTHING;
